node <<'NODE'
const fs = require('node:fs');
const html = fs.readFileSync('superman-ride.html', 'utf8');
const scripts = [...html.matchAll(/<script>([\s\S]*?)<\/script>/g)];
scripts.forEach(([, source]) => new Function(source));
const ids = [...html.matchAll(/\bid="([^"]+)"/g)].map(m => m[1]);
if (new Set(ids).size !== ids.length) throw new Error('Duplicate IDs');
const refs = [...html.matchAll(/(?:href="#|url\(#)([\w-]+)/g)].map(m => m[1]);
refs.forEach(id => { if (!ids.includes(id)) throw new Error('Missing SVG reference: ' + id); });
if (/(?:src|href)="https?:/.test(html)) throw new Error('External dependency');
console.log('PASS: JavaScript syntax, unique IDs, SVG references, no external dependencies');
console.log('File: superman-ride.html | ' + Buffer.byteLength(html) + ' bytes');
NODE
